/**
 * Encrypted backups (blueprint 06 §8).
 *
 * AES-GCM with a key derived from the user's passphrase via PBKDF2-SHA256.
 * Everything comes from the Web Crypto API — no dependency, no key escrow, and
 * no way for anyone (including us) to recover the contents without the
 * passphrase. The UI says so plainly before the user commits to one.
 *
 * The envelope keeps `format`, `schemaVersion`, and the KDF parameters in
 * cleartext so the restore screen can tell a TemuDua file from a random one,
 * and can refuse a future version, without needing the passphrase first.
 */

export const ENCRYPTED_FORMAT = 'temudua-backup-encrypted'

/**
 * 210 000 rounds — the OWASP 2023 floor for PBKDF2-SHA256. Roughly 0.3 s on a
 * mid-range Android, which is the right trade for a file the user unlocks once.
 */
export const PBKDF2_ITERATIONS = 210_000
const SALT_BYTES = 16
const IV_BYTES = 12

export interface EncryptedEnvelope {
  format: typeof ENCRYPTED_FORMAT
  /** Payload schema version, readable without the passphrase. */
  schemaVersion: number
  kdf: 'PBKDF2-SHA256'
  iterations: number
  salt: string
  iv: string
  cipher: string
  createdAt: string
}

export class DecryptError extends Error {}

function toB64(bytes: ArrayBuffer | Uint8Array): string {
  const arr = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes)
  let s = ''
  for (const b of arr) s += String.fromCharCode(b)
  return btoa(s)
}

function fromB64(b64: string): Uint8Array {
  const bin = atob(b64)
  const out = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i)
  return out
}

async function deriveKey(passphrase: string, salt: Uint8Array, iterations: number): Promise<CryptoKey> {
  const material = await crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(passphrase),
    'PBKDF2',
    false,
    ['deriveKey'],
  )
  return crypto.subtle.deriveKey(
    { name: 'PBKDF2', salt: salt as BufferSource, iterations, hash: 'SHA-256' },
    material,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt'],
  )
}

export async function encryptBackup(
  payload: unknown,
  passphrase: string,
  schemaVersion: number,
): Promise<EncryptedEnvelope> {
  const salt = crypto.getRandomValues(new Uint8Array(SALT_BYTES))
  const iv = crypto.getRandomValues(new Uint8Array(IV_BYTES))
  const key = await deriveKey(passphrase, salt, PBKDF2_ITERATIONS)
  const cipher = await crypto.subtle.encrypt(
    { name: 'AES-GCM', iv: iv as BufferSource },
    key,
    new TextEncoder().encode(JSON.stringify(payload)),
  )
  return {
    format: ENCRYPTED_FORMAT,
    schemaVersion,
    kdf: 'PBKDF2-SHA256',
    iterations: PBKDF2_ITERATIONS,
    salt: toB64(salt),
    iv: toB64(iv),
    cipher: toB64(cipher),
    createdAt: new Date().toISOString(),
  }
}

/** True when the text is a TemuDua encrypted package — checkable without a key. */
export function isEncrypted(raw: string): boolean {
  try {
    const j = JSON.parse(raw) as { format?: unknown }
    return j?.format === ENCRYPTED_FORMAT
  } catch {
    return false
  }
}

export function parseEnvelope(raw: string): EncryptedEnvelope {
  let json: unknown
  try {
    json = JSON.parse(raw)
  } catch {
    throw new DecryptError('bukan JSON')
  }
  const e = json as Partial<EncryptedEnvelope>
  if (
    e?.format !== ENCRYPTED_FORMAT ||
    e.kdf !== 'PBKDF2-SHA256' ||
    typeof e.salt !== 'string' ||
    typeof e.iv !== 'string' ||
    typeof e.cipher !== 'string' ||
    typeof e.iterations !== 'number'
  ) {
    throw new DecryptError('envelope tidak lengkap')
  }
  // A hostile file could ask for a billion rounds and hang the tab.
  if (e.iterations < 100_000 || e.iterations > 1_000_000) {
    throw new DecryptError('parameter KDF di luar batas wajar')
  }
  return e as EncryptedEnvelope
}

/**
 * Decrypts, or throws `DecryptError`. AES-GCM authenticates the ciphertext, so
 * a wrong passphrase and a tampered file are indistinguishable here — both are
 * simply "cannot open", which is the honest thing to tell the user.
 */
export async function decryptBackup(raw: string, passphrase: string): Promise<unknown> {
  const env = parseEnvelope(raw)
  const key = await deriveKey(passphrase, fromB64(env.salt), env.iterations)
  let plain: ArrayBuffer
  try {
    plain = await crypto.subtle.decrypt(
      { name: 'AES-GCM', iv: fromB64(env.iv) as BufferSource },
      key,
      fromB64(env.cipher) as BufferSource,
    )
  } catch {
    throw new DecryptError('kata sandi salah atau file rusak')
  }
  try {
    return JSON.parse(new TextDecoder().decode(plain))
  } catch {
    throw new DecryptError('isi file rusak')
  }
}
