import { db, logAudit, OWNED_STORES } from '@/db/db'
import type { Envelope } from '@/types/domain'

/**
 * Safe uncoupling — the data half (TRUST-04, blueprint 05 §5).
 *
 * Kept out of the React component so it can be tested directly. The rules it
 * enforces are the non-negotiables from the governance doc:
 *
 *   - private data never crosses to the other profile, in any mode
 *   - after the cutoff the ex-partner cannot read a single shared record
 *   - the unsafe path writes nothing the partner could notice
 *   - there is no silent route back in
 */

export type SharedChoice = 'copy_both' | 'keep_mine' | 'delete_shared'
export type SafetyPath = 'normal' | 'unsafe'

export interface UncoupleOptions {
  actorProfileId: string
  partnerProfileId: string
  sharedChoice: SharedChoice
  safetyPath: SafetyPath
}

export interface UncoupleResult {
  detached: number
  deleted: number
  untouched: number
  cutoffAt: string
}

export async function performUncoupling(opts: UncoupleOptions): Promise<UncoupleResult> {
  const { actorProfileId: me, partnerProfileId: them, sharedChoice, safetyPath } = opts
  const cutoffAt = new Date().toISOString()
  let detached = 0
  let deleted = 0
  let untouched = 0

  for (const store of OWNED_STORES) {
    const rows = (await db.table(store).toArray()) as Envelope[]
    for (const r of rows) {
      const mine = r.ownerProfileId === me
      const shared =
        r.visibility === 'shared' ||
        r.visibility === 'both_partners' ||
        r.coOwnerProfileIds.includes(them) ||
        r.coOwnerProfileIds.includes(me)

      if (mine && !shared) {
        // My private data. Nothing to revoke, nothing to move.
        untouched++
        continue
      }

      if (!mine && !shared) {
        // Their private data. It was never readable here; leave the row alone
        // so their own copy is not corrupted, and make sure it stays closed.
        await db.table(store).update(r.id, { revokedAt: cutoffAt, sharedWithProfileIds: [] })
        detached++
        continue
      }

      if (sharedChoice === 'delete_shared') {
        await db.table(store).update(r.id, { deletedAt: cutoffAt, revokedAt: cutoffAt })
        deleted++
        continue
      }

      if (sharedChoice === 'keep_mine' && !mine) {
        await db.table(store).update(r.id, { deletedAt: cutoffAt, revokedAt: cutoffAt })
        deleted++
        continue
      }

      // copy_both, or keep_mine on a record I own: cut the link and keep it.
      // The record becomes private to whoever owned it; the partner's own
      // device keeps its own row, which is what "sama-sama simpan" means when
      // there is no server to duplicate through.
      await db.table(store).update(r.id, {
        visibility: 'private',
        coOwnerProfileIds: [],
        sharedWithProfileIds: [],
        revokedAt: cutoffAt,
        updatedAt: cutoffAt,
        version: r.version + 1,
      })
      detached++
    }
  }

  const pair = (await db.pairs.toArray()).find((p) => p.status === 'active')
  if (pair) await db.pairs.update(pair.id, { status: 'uncoupled', uncoupledAt: cutoffAt })

  // Health sharing is revoked unconditionally — it is never something you leave
  // switched on by accident after a separation.
  await db.settings.put({ key: 'cycle.shareLevel', value: 'none' })

  await logAudit({
    actorProfileId: me,
    action: 'unpair',
    objectStore: 'pairs',
    objectId: pair?.id ?? '-',
    summary: `pemisahan akses (${safetyPath === 'unsafe' ? 'jalur aman' : 'biasa'}), data bersama: ${sharedChoice}`,
  })

  return { detached, deleted, untouched, cutoffAt }
}
