import { useState } from 'react'
import { format } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { Sheet } from '@/components/ui'
import { useSession } from '@/app/session'
import { exportBackup } from '@/db/backup'
import { performUncoupling } from './unpair'
import { downloadJson } from '@/utils/download'
import { useT } from '@/i18n'

/**
 * Safe uncoupling (TRUST-04, blueprint 05 §5).
 *
 * Non-negotiables encoded here:
 *   - the unsafe path never sends the partner anything, not even a status change
 *   - private data is never copied to the other profile, in any mode
 *   - the person leaving gets their own export before access is cut
 *   - there is no silent recovery route back in afterwards
 */
export function Uncoupling({ open, onClose }: { open: boolean; onClose: () => void }) {
  const t = useT()
  const { profile, partner, refresh } = useSession()
  const [step, setStep] = useState(0)
  const [safe, setSafe] = useState<'normal' | 'unsafe' | null>(null)
  const [sharedChoice, setSharedChoice] = useState<'copy_both' | 'keep_mine' | 'delete_shared'>('copy_both')
  const [exported, setExported] = useState(false)
  const [busy, setBusy] = useState(false)
  const [done, setDone] = useState<string | null>(null)

  if (!profile || !partner) return null

  async function exportMine() {
    setBusy(true)
    try {
      const pkg = await exportBackup({ actorProfileId: profile!.id, includeSensitive: true })
      downloadJson(`temudua-${profile!.displayName}-${format(new Date(), 'yyyy-MM-dd')}.json`, pkg)
      setExported(true)
    } finally {
      setBusy(false)
    }
  }

  async function finish() {
    setBusy(true)
    try {
      const r = await performUncoupling({
        actorProfileId: profile!.id,
        partnerProfileId: partner!.id,
        sharedChoice,
        safetyPath: safe ?? 'normal',
      })
      await refresh()
      setDone(
        t('unp.done', { detached: r.detached, deleted: r.deleted, untouched: r.untouched }),
      )
    } finally {
      setBusy(false)
    }
  }

  return (
    <Sheet open={open} onClose={onClose} title={t('priv.unpair')}>
      {done ? (
        <div className="stack">
          <p className="banner">
            <Icon name="check" size={18} /> {done}
          </p>
          <p className="card__hint">{t('unp.doneHint')}
          </p>
          <button className="btn btn--block" onClick={onClose}>
            {t('common.done')}
          </button>
        </div>
      ) : (
        <div className="stack">
          {step === 0 && (
            <>
              <p>{t('unp.safeQ')}</p>
              <div className="choices" role="radiogroup" aria-label={t('unp.safeGroup')}>
                <button
                  type="button"
                  role="radio"
                  aria-checked={safe === 'normal'}
                  className="choice"
                  onClick={() => setSafe('normal')}
                >
                  <span className="stack stack--tight">
                    <span className="choice__title">{t('unp.safe.normal')}</span>
                    <span className="choice__desc">{t('unp.safe.normal.desc')}</span>
                  </span>
                </button>
                <button
                  type="button"
                  role="radio"
                  aria-checked={safe === 'unsafe'}
                  className="choice"
                  onClick={() => setSafe('unsafe')}
                >
                  <span className="stack stack--tight">
                    <span className="choice__title">{t('unp.safe.unsafe')}</span>
                    <span className="choice__desc">{t('unp.safe.unsafe.desc')}
                    </span>
                  </span>
                </button>
              </div>
              {safe === 'unsafe' && (
                <p className="banner banner--warn">
                  <Icon name="shield" size={18} />
                  {t('unp.unsafeNote')}
                </p>
              )}
              <button className="btn btn--block" disabled={!safe} onClick={() => setStep(1)}>
                {t('common.next')}
              </button>
            </>
          )}

          {step === 1 && (
            <>
              <h3>{t('unp.exportFirst')}</h3>
              <p className="card__hint">{t('unp.exportFirstHint')}
              </p>
              <button className="btn btn--block" disabled={busy} onClick={exportMine}>
                <Icon name="export" size={18} /> {exported ? t('unp.saveAgain') : t('unp.saveMine')}
              </button>
              <button className="btn btn--ghost btn--block" onClick={() => setStep(2)}>
                {exported ? t('common.next') : t('unp.skipExport')}
              </button>
            </>
          )}

          {step === 2 && (
            <>
              <h3>{t('unp.sharedQ')}</h3>
              <p className="card__hint">{t('unp.sharedHint')}</p>
              <div className="choices" role="radiogroup" aria-label={t('unp.sharedGroup')}>
                {(
                  [
                    'copy_both',
                    'keep_mine',
                    'delete_shared',
                  ] as const
                ).map((v) => (
                  <button
                    key={v}
                    type="button"
                    role="radio"
                    aria-checked={sharedChoice === v}
                    className="choice"
                    onClick={() => setSharedChoice(v)}
                  >
                    <span className="stack stack--tight">
                      <span className="choice__title">{t(`unp.${v}` as const)}</span>
                      <span className="choice__desc">{t(`unp.${v}.desc` as const)}</span>
                    </span>
                  </button>
                ))}
              </div>
              <button className="btn btn--block" onClick={() => setStep(3)}>
                {t('common.next')}
              </button>
            </>
          )}

          {step === 3 && (
            <>
              <h3>{t('unp.checkAgain')}</h3>
              <ul className="list">
                <li className="list__item">
                  <Icon name="private" size={18} />
                  <span className="grow">{t('unp.point1')}</span>
                </li>
                <li className="list__item">
                  <Icon name="unpair" size={18} />
                  <span className="grow">{t('unp.point2', { name: partner.displayName })}</span>
                </li>
                <li className="list__item">
                  <Icon name="shield" size={18} />
                  <span className="grow">{t('unp.point3')}</span>
                </li>
                <li className="list__item">
                  <Icon name="close" size={18} />
                  <span className="grow">{t('unp.point4')}</span>
                </li>
              </ul>
              <p className="banner banner--warn">
                <Icon name="info" size={18} />{t('unp.irreversible')}
              </p>
              <button className="btn btn--danger btn--block" disabled={busy} onClick={finish}>
                {busy ? t('unp.processing') : t('unp.confirm')}
              </button>
              <button className="btn btn--ghost btn--block" onClick={onClose}>
                {t('common.cancel')}
              </button>
            </>
          )}
        </div>
      )}
    </Sheet>
  )
}
