import { useRef, useState } from 'react'
import { useLiveQuery } from 'dexie-react-hooks'
import { format } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { useSession } from '@/app/session'
import { db, OWNED_STORES, type OwnedStore } from '@/db/db'
import {
  exportBackup,
  parseBackup,
  previewRestore,
  restoreBackup,
  type BackupPackage,
  type RestoreMode,
  type RestorePreview,
} from '@/db/backup'
import { Uncoupling } from './Uncoupling'
import { downloadJson } from '@/utils/download'
import { DecryptError, decryptBackup, encryptBackup, isEncrypted } from '@/security/crypto'
import { SCHEMA_VERSION } from '@/types/domain'
import { useI18n } from '@/i18n'
import { fmtDate } from '@/i18n/format'

/**
 * Privasi & data (TRUST-01..04).
 *
 * Everything destructive on this screen previews before it acts, and everything
 * that moves data writes an audit entry.
 */
export default function Privacy() {
  const { t, locale } = useI18n()
  const { profile, partner } = useSession()
  const [includeSensitive, setIncludeSensitive] = useState(false)
  const [busy, setBusy] = useState(false)
  const [message, setMessage] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [pending, setPending] = useState<{ pkg: BackupPackage; preview: RestorePreview } | null>(null)
  const [encrypt, setEncrypt] = useState(false)
  const [pass, setPass] = useState('')
  const [pass2, setPass2] = useState('')
  // Set when the chosen file is encrypted and still needs a passphrase.
  const [locked, setLocked] = useState<string | null>(null)
  const [unlockPass, setUnlockPass] = useState('')
  const [unpairOpen, setUnpairOpen] = useState(false)
  const fileRef = useRef<HTMLInputElement>(null)

  const audit = useLiveQuery(() => db.audit.reverse().limit(25).toArray(), [])
  const counts = useLiveQuery(async () => {
    const entries = await Promise.all(
      OWNED_STORES.map(async (s) => [s, await db.table(s).count()] as const),
    )
    return Object.fromEntries(entries) as Record<string, number>
  }, [])

  if (!profile) return null
  const total = Object.values(counts ?? {}).reduce((a, b) => a + b, 0)

  async function doExport() {
    setBusy(true)
    setError(null)
    try {
      const pkg = await exportBackup({ actorProfileId: profile!.id, includeSensitive })
      const stamp = format(new Date(), 'yyyy-MM-dd')
      if (encrypt) {
        const sealed = await encryptBackup(pkg, pass, SCHEMA_VERSION)
        downloadJson(`temudua-backup-${stamp}.temudua.json`, sealed)
      } else {
        downloadJson(`temudua-backup-${stamp}.json`, pkg)
      }
      setPass('')
      setPass2('')
      setMessage(t('priv.backupDone'))
    } catch (e) {
      setError(e instanceof Error ? e.message : t('priv.backupFailed'))
    } finally {
      setBusy(false)
    }
  }

  async function onFile(file: File) {
    setError(null)
    setMessage(null)
    try {
      const raw = await file.text()
      // An encrypted file is recognisable without the passphrase, so we can ask
      // for one instead of showing "this is not a TemuDua file".
      if (isEncrypted(raw)) {
        setLocked(raw)
        return
      }
      const pkg = parseBackup(raw)
      setPending({ pkg, preview: await previewRestore(pkg) })
    } catch (e) {
      setError(e instanceof Error ? e.message : t('priv.restoreError'))
    } finally {
      if (fileRef.current) fileRef.current.value = ''
    }
  }

  async function unlock() {
    if (!locked) return
    setBusy(true)
    setError(null)
    try {
      const plain = await decryptBackup(locked, unlockPass)
      const pkg = parseBackup(JSON.stringify(plain))
      setPending({ pkg, preview: await previewRestore(pkg) })
      setLocked(null)
      setUnlockPass('')
    } catch (e) {
      setError(e instanceof DecryptError ? t('priv.wrongPassword') : t('priv.restoreError'))
    } finally {
      setBusy(false)
    }
  }

  async function doRestore(mode: RestoreMode) {
    if (!pending) return
    setBusy(true)
    try {
      const r = await restoreBackup(pending.pkg, mode, profile!.id)
      setMessage(t('priv.restoreDone', { written: r.written, skipped: r.skipped }))
      setPending(null)
    } catch (e) {
      setError(e instanceof Error ? e.message : t('priv.restoreFailed'))
    } finally {
      setBusy(false)
    }
  }

  return (
    <div className="stack">
      <h1>{t('priv.title')}</h1>
      <p className="card__hint">{t('priv.subtitle')}
      </p>

      {message && (
        <p className="banner" role="status">
          <Icon name="info" size={18} /> {message}
        </p>
      )}
      {error && (
        <p className="banner banner--danger" role="alert">
          <Icon name="emergency" size={18} /> {error}
        </p>
      )}

      <Card title={t('priv.backup')} icon="backup" hint={t('priv.backupCount', { n: total })}>
        <label className="choice" style={{ cursor: 'pointer' }}>
          <input
            type="checkbox"
            checked={includeSensitive}
            onChange={(e) => setIncludeSensitive(e.target.checked)}
            style={{ marginTop: 4 }}
          />
          <span className="stack stack--tight">
            <span className="choice__title">{t('priv.includeHealth')}</span>
            <span className="choice__desc">{t('priv.includeHealthDesc')}
            </span>
          </span>
        </label>
        <label className="choice" style={{ cursor: 'pointer', marginTop: 'var(--space-3)' }}>
          <input
            type="checkbox"
            checked={encrypt}
            onChange={(e) => setEncrypt(e.target.checked)}
            style={{ marginTop: 4 }}
          />
          <span className="stack stack--tight">
            <span className="choice__title">{t('priv.encrypt')}</span>
            <span className="choice__desc">{t('priv.encryptDesc')}</span>
          </span>
        </label>

        {encrypt && (
          <div className="stack stack--tight" style={{ marginTop: 'var(--space-3)' }}>
            <Field
              label={t('priv.password')}
              error={pass && pass.length < 8 ? t('priv.passwordShort') : undefined}
            >
              {(p) => (
                <input
                  {...p}
                  type="password"
                  autoComplete="new-password"
                  value={pass}
                  onChange={(e) => setPass(e.target.value)}
                />
              )}
            </Field>
            <Field
              label={t('priv.passwordAgain')}
              error={pass2 && pass !== pass2 ? t('priv.passwordMismatch') : undefined}
            >
              {(p) => (
                <input
                  {...p}
                  type="password"
                  autoComplete="new-password"
                  value={pass2}
                  onChange={(e) => setPass2(e.target.value)}
                />
              )}
            </Field>
          </div>
        )}

        <button
          className="btn btn--block"
          disabled={busy || (encrypt && (pass.length < 8 || pass !== pass2))}
          onClick={doExport}
          style={{ marginTop: 'var(--space-3)' }}
        >
          <Icon name="export" size={18} /> {t('priv.makeBackup')}
        </button>
      </Card>

      <Card title={t('priv.restore')} icon="restore" hint={t('priv.restoreHint')}>
        <input
          ref={fileRef}
          type="file"
          accept="application/json,.json"
          aria-label={t('priv.pickFile')}
          onChange={(e) => {
            const f = e.target.files?.[0]
            if (f) onFile(f)
          }}
        />
      </Card>

      {partner && (
        <Card title={t('priv.unpair')} icon="unpair" hint={t('priv.unpairHint')}>
          <button className="btn btn--ghost btn--block" onClick={() => setUnpairOpen(true)}>
            <Icon name="unpair" size={18} />{t('priv.startUnpair')}
          </button>
        </Card>
      )}

      <Card title={t('priv.auditLog')} icon="shield" hint={t('priv.auditHint')}>
        {(audit ?? []).length === 0 ? (
          <EmptyState icon="shield" title={t('priv.noAudit')} />
        ) : (
          <ul className="list">
            {(audit ?? []).map((a) => (
              <li key={a.seq} className="list__item">
                <Icon name={auditIcon(a.action)} size={18} />
                <span className="grow stack stack--tight">
                  <strong style={{ fontSize: 13 }}>
                    {t(`audit.${a.action}` as const)} · {a.objectStore}
                  </strong>
                  <span className="card__hint">
                    {fmtDate(a.timestamp, 'd MMM yyyy, HH:mm', locale)} — {a.summary}
                  </span>
                </span>
              </li>
            ))}
          </ul>
        )}
      </Card>

      <Sheet open={pending !== null} onClose={() => setPending(null)} title={t('priv.checkFirst')}>
        {pending && (
          <div className="stack">
            <p className="card__hint">
              {t('priv.madeOn', {
                date: fmtDate(pending.preview.exportedAt, 'd MMMM yyyy, HH:mm', locale),
                version: pending.preview.schemaVersion,
              })}
            </p>
            <ul className="list">
              {Object.entries(pending.preview.counts)
                .filter(([, n]) => n > 0)
                .map(([store, n]) => (
                  <li key={store} className="list__item">
                    <span className="grow">{t(`store.${store as OwnedStore}` as const)}</span>
                    <span className="chip">{n}</span>
                  </li>
                ))}
            </ul>
            {pending.preview.conflicts > 0 && (
              <p className="banner banner--warn">
                <Icon name="info" size={18} />
                {t('priv.conflicts', { n: pending.preview.conflicts })}
              </p>
            )}
            <div className="stack stack--tight">
              <button className="btn btn--block" disabled={busy} onClick={() => doRestore('merge_keep_local')}>{t('priv.mergeKeepLocal')}
              </button>
              <button className="btn btn--ghost btn--block" disabled={busy} onClick={() => doRestore('merge_use_imported')}>{t('priv.mergeUseImported')}
              </button>
              <button className="btn btn--danger btn--block" disabled={busy} onClick={() => doRestore('replace')}>{t('priv.replaceAll')}
              </button>
            </div>
          </div>
        )}
      </Sheet>

      <Sheet
        open={locked !== null}
        onClose={() => {
          setLocked(null)
          setUnlockPass('')
        }}
        title={t('priv.openEncrypted')}
      >
        <div className="stack">
          <Field label={t('priv.passwordToOpen')}>
            {(p) => (
              <input
                {...p}
                type="password"
                autoComplete="current-password"
                value={unlockPass}
                onChange={(e) => setUnlockPass(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') unlock()
                }}
              />
            )}
          </Field>
          <button className="btn btn--block" disabled={busy || !unlockPass} onClick={unlock}>
            {t('priv.openEncrypted')}
          </button>
        </div>
      </Sheet>

      <Uncoupling open={unpairOpen} onClose={() => setUnpairOpen(false)} />
    </div>
  )
}

function auditIcon(a: string) {
  return (
    ({ share: 'shared', revoke: 'private', export: 'export', restore: 'restore', unpair: 'unpair' } as const)[
      a as 'share'
    ] ?? 'shield'
  )
}
